def find_max(values):
    max_value = values[0]

    for value in values:
        if value > max_value:
            max_value = value

    return max_value

print(find_max([7, 2, 11, 4, 9]))

def countdown(n):
    if n == 0:
        return

    print(n)
    countdown(n - 1)

countdown(5)

def iterative_binary_search(values, target):
    low = 0
    high = len(values) - 1

    while low <= high:
        mid = (low + high) // 2
        if values[mid] == target:
            return mid
        if values[mid] < target:
            low = mid + 1
        else:
            high = mid - 1

    return -1

print(iterative_binary_search([2, 4, 8, 16, 32], 16))
